{
  "themes": [
    {
      "cluster": 0,
      "name": "Delivery Delays and Missing Packages",
      "description": "Customers complain that orders arrive late, are delayed, or never get delivered despite promised shipping times."
    },
    {
      "cluster": 1,
      "name": "In‑App Contest Winner Transparency",
      "description": "Users ask where to find contest results, why they aren’t selected as winners, and report not being contacted after winning."
    },
    {
      "cluster": 2,
      "name": "Kindle Device Availability and Promotions",
      "description": "Feedback focuses on buying Kindle devices, regional availability, warranty questions, and requests for discounts or promotions."
    },
    {
      "cluster": 3,
      "name": "Courier Service Timing and Handling Issues",
      "description": "Customers express frustration with Amazon couriers arriving late, losing packages, or handling items roughly."
    },
    {
      "cluster": 4,
      "name": "French‑Speaking Shipping Cost and Prime Concerns",
      "description": "French‑language users question one‑day delivery fees, delivery failures, and the value of Prime membership."
    },
    {
      "cluster": 5,
      "name": "Order Damage and Late Arrival Complaints",
      "description": "Buyers report receiving damaged parcels, unsealed boxes, or orders arriving far later than promised."
    },
    {
      "cluster": 6,
      "name": "Prime Membership Delivery Guarantees",
      "description": "Members are upset about Prime items taking longer than the promised 1‑day/next‑day service and issues with refunds or transfers."
    },
    {
      "cluster": 7,
      "name": "Headphone/Earphone Order Problems",
      "description": "Customers mention receiving damaged or opened headphones, delayed shipments, and requests for product recommendations or returns."
    },
    {
      "cluster": 8,
      "name": "Prime Video Content Availability",
      "description": "Users request missing seasons, language tracks, app installations on TV sticks, and report playback failures."
    },
    {
      "cluster": 9,
      "name": "Alexa/Echo Feature and Setup Help",
      "description": "Feedback includes requests for Alexa voice training, contact/messaging features, and issues with device connectivity."
    },
    {
      "cluster": 10,
      "name": "Pre‑Order Game Shipping Issues",
      "description": "Customers complain about delayed or incomplete pre‑ordered game shipments, missing discs, and poor communication."
    },
    {
      "cluster": 11,
      "name": "Kindle Book Delivery and App Functionality",
      "description": "Users report problems with Kindle book delivery, missing titles, app UI issues, and device display settings."
    }
  ]
}
